import { readFileSync } from "fs";

const lines = readFileSync(0, "utf8").trim().split("\n");
const [h, w] = lines[0].split(" ").map(Number);
const a = lines.slice(1, h + 1).map((line) => line.split(" ").map(Number));

const out: string[] = [];
for (let j = 0; j < w; j++) {
  // 元の行列の j 列目を縦に読んだものが、転置の j 行目
  const row: number[] = [];
  for (let i = 0; i < h; i++) row.push(a[i][j]);
  out.push(row.join(" "));
}
console.log(out.join("\n"));
